// One entry point for tools and agents:  reviewGame(options)  and  compareRuns(beforeDir, afterDir)
// The CLI (review.mjs, compare.mjs) and the SHADDAI MCP both go through here.
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { join } from 'node:path';
import { capture } from './capture.mjs';
import { buildReport, markdown } from './report.mjs';
import { compareReports } from './compare.mjs';

export const LIMITS = { maxSeconds: 60, maxShots: 12, minSize: 200, maxSize: 3840, maxActions: 100 };

// Hosts a local review may open without an explicit opt-in: your own machine and private networks.
export function isLocalUrl(u) {
  let url;
  try { url = new URL(u); } catch { return false; }
  if (url.protocol === 'file:') return true;
  if (url.protocol !== 'http:' && url.protocol !== 'https:') return false;
  const h = url.hostname.replace(/^\[|\]$/g, '');
  return h === 'localhost' || h === '::1' || /^127\./.test(h) || /^10\./.test(h) || /^192\.168\./.test(h) || /^172\.(1[6-9]|2\d|3[01])\./.test(h) || h.endsWith('.local');
}

export function validate(o) {
  if (!o.url || typeof o.url !== 'string') throw new Error('url is required');
  if (!isLocalUrl(o.url) && !o.allowRemote) throw new Error('only local URLs (localhost, 127.x, private networks, file://) are allowed unless allowRemote is true');
  const clamp = (v, lo, hi, d) => Math.min(hi, Math.max(lo, Number.isFinite(+v) && v !== undefined ? +v : d));
  const actions = Array.isArray(o.actions) ? o.actions : [];
  if (actions.length > LIMITS.maxActions) throw new Error(`too many actions (max ${LIMITS.maxActions})`);
  for (const a of actions) {
    if (!(a && typeof a.at === 'number' && a.at >= 0 && a.at <= LIMITS.maxSeconds)) throw new Error('every action needs an "at" time in seconds');
    if (a.key !== undefined && (typeof a.key !== 'string' || a.key.length > 20)) throw new Error('action key must be a short string');
    if (a.type !== undefined && (typeof a.type !== 'string' || a.type.length > 200)) throw new Error('action type text is too long');
    if (a.click !== undefined && !(Array.isArray(a.click) && a.click.length === 2 && a.click.every((n) => Number.isFinite(n)))) throw new Error('action click must be [x, y]');
  }
  return {
    url: o.url, actions,
    seconds: clamp(o.seconds, 1, LIMITS.maxSeconds, 8), shots: Math.round(clamp(o.shots, 2, LIMITS.maxShots, 6)),
    width: Math.round(clamp(o.width, LIMITS.minSize, LIMITS.maxSize, 1280)), height: Math.round(clamp(o.height, LIMITS.minSize, LIMITS.maxSize, 720)),
  };
}

export async function reviewGame(options, outDir) {
  const opts = validate(options);
  mkdirSync(outDir, { recursive: true });
  const raw = await capture({ ...opts, outDir });
  const report = buildReport(raw);
  writeFileSync(join(outDir, 'report.json'), JSON.stringify(report, null, 2));
  writeFileSync(join(outDir, 'REPORT.md'), markdown(report));
  return { report, markdown: markdown(report), dir: outDir, contactSheet: join(outDir, 'contact.png') };
}

export function compareRuns(beforeDir, afterDir) {
  const load = (d) => JSON.parse(readFileSync(join(d, 'report.json'), 'utf8'));
  return compareReports(load(beforeDir), load(afterDir));
}

// Minimal PNG reader/writer (no dependencies) — enough to analyse browser screenshots.
// Reads 8-bit greyscale, grey+alpha, RGB and RGBA, non-interlaced. Always returns RGBA.
import { inflateSync, deflateSync } from 'node:zlib';

const SIG = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);
const CHANNELS = { 0: 1, 2: 3, 4: 2, 6: 4 };

export function decodePng(buf) {
  if (!buf.subarray(0, 8).equals(SIG)) throw new Error('not a PNG file');
  let pos = 8, w = 0, h = 0, depth = 0, type = 0, interlace = 0;
  const idat = [];
  while (pos + 8 <= buf.length) {
    const len = buf.readUInt32BE(pos), kind = buf.toString('ascii', pos + 4, pos + 8), body = buf.subarray(pos + 8, pos + 8 + len);
    if (kind === 'IHDR') { w = body.readUInt32BE(0); h = body.readUInt32BE(4); depth = body[8]; type = body[9]; interlace = body[12]; }
    else if (kind === 'IDAT') idat.push(body);
    else if (kind === 'IEND') break;
    pos += 12 + len;
  }
  if (!w || !h) throw new Error('PNG has no header');
  if (depth !== 8) throw new Error(`unsupported PNG bit depth ${depth} (need 8)`);
  if (!(type in CHANNELS)) throw new Error(`unsupported PNG colour type ${type} (palette images are not supported)`);
  if (interlace) throw new Error('interlaced PNGs are not supported');

  const bpp = CHANNELS[type], stride = w * bpp;
  const raw = inflateSync(Buffer.concat(idat));
  if (raw.length < h * (stride + 1)) throw new Error('PNG data is truncated');
  const px = Buffer.alloc(h * stride);
  for (let y = 0; y < h; y++) {
    const filter = raw[y * (stride + 1)], src = y * (stride + 1) + 1, dst = y * stride;
    for (let x = 0; x < stride; x++) {
      const cur = raw[src + x];
      const a = x >= bpp ? px[dst + x - bpp] : 0;
      const b = y > 0 ? px[dst - stride + x] : 0;
      const c = x >= bpp && y > 0 ? px[dst - stride + x - bpp] : 0;
      let v;
      switch (filter) {
        case 0: v = cur; break;
        case 1: v = cur + a; break;
        case 2: v = cur + b; break;
        case 3: v = cur + ((a + b) >> 1); break;
        case 4: { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); v = cur + (pa <= pb && pa <= pc ? a : pb <= pc ? b : c); break; }
        default: throw new Error('bad PNG filter ' + filter);
      }
      px[dst + x] = v & 255;
    }
  }
  const data = new Uint8ClampedArray(w * h * 4);
  for (let i = 0; i < w * h; i++) {
    const s = i * bpp, o = i * 4;
    if (type === 6) { data[o] = px[s]; data[o + 1] = px[s + 1]; data[o + 2] = px[s + 2]; data[o + 3] = px[s + 3]; }
    else if (type === 2) { data[o] = px[s]; data[o + 1] = px[s + 1]; data[o + 2] = px[s + 2]; data[o + 3] = 255; }
    else { data[o] = data[o + 1] = data[o + 2] = px[s]; data[o + 3] = type === 4 ? px[s + 1] : 255; }
  }
  return { width: w, height: h, data };
}

const CRC = (() => { const t = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; t[n] = c >>> 0; } return t; })();
const crc32 = (buf) => { let c = 0xffffffff; for (const b of buf) c = CRC[(c ^ b) & 255] ^ (c >>> 8); return (c ^ 0xffffffff) >>> 0; };

function chunk(kind, body) {
  const out = Buffer.alloc(12 + body.length), tag = Buffer.from(kind, 'ascii');
  out.writeUInt32BE(body.length, 0); tag.copy(out, 4); body.copy(out, 8);
  out.writeUInt32BE(crc32(Buffer.concat([tag, body])), 8 + body.length);
  return out;
}

// image: { width, height, data: RGBA }
export function encodePng({ width, height, data }) {
  const rows = Buffer.alloc(height * (width * 4 + 1));
  for (let y = 0; y < height; y++) {
    rows[y * (width * 4 + 1)] = 0;
    Buffer.from(data.buffer, data.byteOffset + y * width * 4, width * 4).copy(rows, y * (width * 4 + 1) + 1);
  }
  const head = Buffer.alloc(13);
  head.writeUInt32BE(width, 0); head.writeUInt32BE(height, 4); head[8] = 8; head[9] = 6;
  return Buffer.concat([SIG, chunk('IHDR', head), chunk('IDAT', deflateSync(rows)), chunk('IEND', Buffer.alloc(0))]);
}

// Runs a game in headless Chromium and records what a player would see and what the machine saw.
// Needs Playwright:  npm i -D playwright && npx playwright install chromium
// (or set GAME_REVIEW_BROWSER to the path of any installed Chrome/Chromium/Edge)
//
// Optional hook: if the game defines  window.__gameProbe = () => ({ drawCalls, triangles, ... })
// the numbers are included in the report (e.g. return renderer.info.render.calls).
//
// actions: [{ at: seconds, key: 'ArrowRight', hold: 0.4 } | { at, click: [x, y] } | { at, type: 'text' }]
import { mkdirSync, writeFileSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export async function capture({ url, seconds = 8, shots = 6, width = 1280, height = 720, actions = [], outDir }) {
  let chromium;
  try { ({ chromium } = await import('playwright')); }
  catch { throw new Error('Playwright is not installed. Run: npm i -D playwright && npx playwright install chromium'); }
  mkdirSync(outDir, { recursive: true });

  // GAME_REVIEW_BROWSER=<path to chrome/chromium/edge> uses an existing browser instead of Playwright's own download.
  const browser = await chromium.launch(process.env.GAME_REVIEW_BROWSER ? { executablePath: process.env.GAME_REVIEW_BROWSER } : {});
  const page = await browser.newPage({ viewport: { width, height }, deviceScaleFactor: 1 });
  const consoleLog = [], failed = [];
  page.on('console', (m) => consoleLog.push({ type: m.type(), text: m.text() }));
  page.on('pageerror', (e) => consoleLog.push({ type: 'pageerror', text: String((e && e.message) || e) }));
  page.on('requestfailed', (r) => failed.push({ url: r.url(), status: 0 }));
  page.on('response', (r) => { if (r.status() >= 400) failed.push({ url: r.url(), status: r.status() }); });
  await page.addInitScript(() => {
    window.__frameTimes = [];
    let last = performance.now();
    (function tick(now) { window.__frameTimes.push(now - last); last = now; if (window.__frameTimes.length < 4000) requestAnimationFrame(tick); })(last);
  });

  await page.goto(url, { waitUntil: 'load', timeout: 30000 });

  // One merged, time-ordered list of things to do: screenshots and inputs.
  const events = [];
  for (let i = 0; i < shots; i++) events.push({ at: 0.5 + (i * (seconds - 0.5)) / Math.max(1, shots - 1), shot: i });
  for (const a of actions) events.push({ ...a });
  events.sort((a, b) => a.at - b.at);

  const frames = [];
  let inputs = 0;
  const t0 = Date.now();
  for (const ev of events) {
    const wait = ev.at * 1000 - (Date.now() - t0);
    if (wait > 0) await sleep(wait);
    if (ev.shot !== undefined) {
      const file = join(outDir, `shot-${String(ev.shot).padStart(2, '0')}.png`);
      await page.screenshot({ path: file });
      frames.push({ t: +((Date.now() - t0) / 1000).toFixed(2), file });
    } else if (ev.key) {
      await page.keyboard.down(ev.key); await sleep((ev.hold ?? 0.15) * 1000); await page.keyboard.up(ev.key); inputs++;
    } else if (ev.click) { await page.mouse.click(ev.click[0], ev.click[1]); inputs++; }
    else if (ev.type) { await page.keyboard.type(ev.type); inputs++; }
  }

  const canvas = await page.evaluate(() => {
    const all = [...document.querySelectorAll('canvas')].map((c) => { const r = c.getBoundingClientRect(); return { w: r.width, h: r.height, x: r.left, y: r.top, vw: innerWidth, vh: innerHeight }; });
    all.sort((a, b) => b.w * b.h - a.w * a.h);
    return all[0] || null;
  });
  const times = (await page.evaluate(() => window.__frameTimes || [])).slice(5);
  const probe = await page.evaluate(() => (typeof window.__gameProbe === 'function' ? window.__gameProbe() : null)).catch(() => null);
  const sorted = [...times].sort((a, b) => a - b);
  const mean = times.length ? times.reduce((s, x) => s + x, 0) / times.length : null;
  const perf = {
    fps: mean ? +(1000 / mean).toFixed(1) : null,
    p95FrameMs: sorted.length ? +sorted[Math.floor(sorted.length * 0.95)].toFixed(1) : null,
    maxFrameMs: sorted.length ? +sorted[sorted.length - 1].toFixed(1) : null,
    drawCalls: probe?.drawCalls ?? null, triangles: probe?.triangles ?? null,
  };

  // Contact sheet: all screenshots in one image, so one look shows the whole run.
  const imgs = frames.map((f) => `<figure><img src="data:image/png;base64,${readFileSync(f.file).toString('base64')}"><figcaption>t = ${f.t}s</figcaption></figure>`).join('');
  const sheet = await browser.newPage({ viewport: { width: 1320, height: 800 } });
  await sheet.setContent(`<style>body{margin:8px;background:#111;color:#ccc;font:12px sans-serif;display:grid;grid-template-columns:repeat(3,1fr);gap:8px}img{width:100%;display:block}figure{margin:0}</style>${imgs}`);
  await sheet.screenshot({ path: join(outDir, 'contact.png'), fullPage: true });
  await browser.close();

  return { frames, console: consoleLog, failedRequests: failed, perf, canvas, inputsSent: inputs, viewport: { width, height } };
}

export function loadActions(file) { return file ? JSON.parse(readFileSync(file, 'utf8')) : []; }
