/**
 * SHADDAI Three.js Gamedev Master MCP Bridge
 *
 * Exposes all game-dev skills and templates to:
 * - TURTLE agent (UI/UX, design, prototyping)
 * - NEXUS agent (architecture, performance)
 * - Direct Claude Code sessions
 *
 * Port: 3001 (separate from main SHADDAI MCP on 3000)
 */

const fs = require('fs')
const path = require('path')

const REPO_ROOT = path.resolve(__dirname, '..')
const SKILLS_DIR = path.join(REPO_ROOT, 'SKILLS-HUB', '.claude', 'skills')
const GENRES_DIR = path.join(REPO_ROOT, 'GENRE-TEMPLATES')
const FLAT_LIBRARY_DIR = path.join(REPO_ROOT, 'FLAT-LIBRARY')

/**
 * List all invokable skills
 */
function listSkills() {
  const skills = fs.readdirSync(SKILLS_DIR)
    .filter(dir => fs.statSync(path.join(SKILLS_DIR, dir)).isDirectory())
    .map(skillName => {
      const skillPath = path.join(SKILLS_DIR, skillName, 'SKILL.md')
      if (!fs.existsSync(skillPath)) return null

      const content = fs.readFileSync(skillPath, 'utf8')
      const descMatch = content.match(/description:\s*(.+?)$/m)
      const description = descMatch ? descMatch[1] : ''

      return {
        name: skillName,
        description: description.trim(),
        path: skillPath
      }
    })
    .filter(Boolean)

  return skills
}

/**
 * Invoke a skill (return SKILL.md + example)
 */
function invokeSkill(skillName) {
  const skillPath = path.join(SKILLS_DIR, skillName, 'SKILL.md')
  if (!fs.existsSync(skillPath)) {
    return { error: `Skill "${skillName}" not found` }
  }

  const content = fs.readFileSync(skillPath, 'utf8')
  return {
    skill: skillName,
    documentation: content,
    files: fs.readdirSync(path.join(SKILLS_DIR, skillName))
  }
}

/**
 * List all genre templates
 */
function listGenres() {
  const genres = fs.readdirSync(GENRES_DIR)
    .filter(dir => {
      const fullPath = path.join(GENRES_DIR, dir)
      return fs.statSync(fullPath).isDirectory() &&
             fs.existsSync(path.join(fullPath, 'scaffold'))
    })
    .map(genreName => ({
      name: genreName,
      hasDocs: fs.existsSync(path.join(GENRES_DIR, genreName, 'docs')),
      hasExamples: fs.existsSync(path.join(GENRES_DIR, genreName, 'examples')),
      scaffoldPath: path.join(GENRES_DIR, genreName, 'scaffold')
    }))

  return genres
}

/**
 * Get genre scaffold (starter project structure)
 */
function getGenreScaffold(genreName) {
  const scaffoldPath = path.join(GENRES_DIR, genreName, 'scaffold')
  if (!fs.existsSync(scaffoldPath)) {
    return { error: `Genre "${genreName}" scaffold not found` }
  }

  return {
    genre: genreName,
    scaffoldPath: scaffoldPath,
    files: listDirRecursive(scaffoldPath),
    instructions: `Copy ${scaffoldPath} to your project and follow docs/`
  }
}

/**
 * Search flat library by keyword
 */
function searchFlatLibrary(query) {
  const results = []
  const dirs = fs.readdirSync(FLAT_LIBRARY_DIR)

  for (const category of dirs) {
    const categoryPath = path.join(FLAT_LIBRARY_DIR, category)
    if (!fs.statSync(categoryPath).isDirectory()) continue

    const mdFiles = findMdFiles(categoryPath)
    mdFiles.forEach(file => {
      const content = fs.readFileSync(file, 'utf8')
      if (content.toLowerCase().includes(query.toLowerCase())) {
        results.push({
          category: category,
          file: path.relative(FLAT_LIBRARY_DIR, file),
          path: file
        })
      }
    })
  }

  return results.slice(0, 10)  // Limit results
}

/**
 * Helper: Recursively find .md files
 */
function findMdFiles(dir) {
  let results = []
  const files = fs.readdirSync(dir)

  files.forEach(file => {
    const fullPath = path.join(dir, file)
    if (fs.statSync(fullPath).isDirectory()) {
      results = results.concat(findMdFiles(fullPath))
    } else if (file.endsWith('.md')) {
      results.push(fullPath)
    }
  })

  return results
}

/**
 * Helper: List directory recursively
 */
function listDirRecursive(dir, prefix = '') {
  const items = []
  const files = fs.readdirSync(dir)

  files.forEach(file => {
    const fullPath = path.join(dir, file)
    const stat = fs.statSync(fullPath)

    if (stat.isDirectory()) {
      items.push(`${prefix}${file}/`)
      items.push(...listDirRecursive(fullPath, `${prefix}  `))
    } else {
      items.push(`${prefix}${file}`)
    }
  })

  return items
}

/**
 * MCP Resource Endpoints
 */
const resources = {
  '/skills/list': listSkills,
  '/skills/invoke/:skillName': invokeSkill,
  '/genres/list': listGenres,
  '/genres/scaffold/:genreName': getGenreScaffold,
  '/search/:query': (query) => searchFlatLibrary(query),
  '/registry': () => ({
    skills: listSkills(),
    genres: listGenres(),
    repoPath: REPO_ROOT
  })
}

/**
 * Express-like routing (for manual HTTP server)
 */
function handleRequest(method, path, params) {
  if (method !== 'GET') return { error: 'Only GET supported' }

  // Handle dynamic routes
  if (path.startsWith('/skills/invoke/')) {
    const skillName = path.split('/').pop()
    return invokeSkill(skillName)
  }

  if (path.startsWith('/genres/scaffold/')) {
    const genreName = path.split('/').pop()
    return getGenreScaffold(genreName)
  }

  if (path.startsWith('/search/')) {
    const query = path.split('/').pop()
    return searchFlatLibrary(query)
  }

  // Static routes
  const handler = resources[path]
  if (handler) return handler()

  return { error: `Route not found: ${path}` }
}

module.exports = {
  listSkills,
  invokeSkill,
  listGenres,
  getGenreScaffold,
  searchFlatLibrary,
  handleRequest,
  REPO_ROOT,
  SKILLS_DIR,
  GENRES_DIR,
  FLAT_LIBRARY_DIR
}

// node scripts/audit.mjs — repo health check. Exit code 1 if anything fails.
// Checks: JS syntax · markdown links · skill registry vs files · stale references · MCP bridge loads ·
//         every skill has valid front-matter · test suites pass.
import { readdirSync, readFileSync, existsSync, statSync } from 'node:fs';
import { join, relative, dirname, resolve, sep } from 'node:path';
import { spawnSync } from 'node:child_process';

const root = resolve(new URL('..', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1'));
const SKIP = new Set(['.git', 'node_modules', '__pycache__', '.pytest_cache']);
const problems = [], notes = [];
const fail = (area, msg) => problems.push(`[${area}] ${msg}`);
const rel = (p) => relative(root, p).split(sep).join('/');

function walk(dir, out = []) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (SKIP.has(e.name)) continue;
    const p = join(dir, e.name);
    e.isDirectory() ? walk(p, out) : out.push(p);
  }
  return out;
}
const files = walk(root);
const byExt = (re) => files.filter((f) => re.test(f));

// 1 ── JS syntax
let jsCount = 0;
for (const f of byExt(/\.(m?js)$/)) {
  jsCount++;
  const r = spawnSync(process.execPath, ['--check', f], { encoding: 'utf8' });
  if (r.status !== 0) fail('syntax', `${rel(f)}: ${(r.stderr || '').split('\n').find((l) => l.includes('Error')) || 'does not parse'}`);
}
notes.push(`${jsCount} JS files parsed`);

// 2 ── markdown links
let linkCount = 0;
for (const f of byExt(/\.md$/)) {
  const text = readFileSync(f, 'utf8').replace(/```[\s\S]*?```/g, '');         // ignore code blocks
  for (const m of text.matchAll(/\[[^\]]*\]\(([^)\s]+)\)/g)) {
    let target = m[1].split('#')[0];
    if (!target || /^[a-z]+:|^mailto:/i.test(target)) continue;
    linkCount++;
    const abs = resolve(dirname(f), decodeURIComponent(target));
    if (!existsSync(abs)) fail('links', `${rel(f)} → ${m[1]} (missing)`);
  }
}
notes.push(`${linkCount} relative links checked`);

// 3 ── skill registry ↔ skill files, and front-matter
const registry = join(root, 'SKILLS-HUB', 'SKILL-REGISTRY.md');
const skillDir = join(root, 'SKILLS-HUB', '.claude', 'skills');
const onDisk = existsSync(skillDir) ? readdirSync(skillDir).filter((d) => existsSync(join(skillDir, d, 'SKILL.md'))) : [];
if (existsSync(registry)) {
  const listed = [...readFileSync(registry, 'utf8').matchAll(/^\|\s*`([a-z0-9-]+)`\s*\|/gm)].map((m) => m[1]);
  for (const name of listed) {
    const inFlat = existsSync(join(root, 'FLAT-LIBRARY', 'three-core', name, 'SKILL.md'));
    if (!onDisk.includes(name) && !inFlat) fail('registry', `skill "${name}" is listed but has no SKILL.md`);
  }
  for (const name of onDisk) if (!listed.includes(name)) notes.push(`skill "${name}" exists but is not in the registry`);
  notes.push(`${listed.length} registry entries checked`);
}
for (const d of onDisk) {
  const t = readFileSync(join(skillDir, d, 'SKILL.md'), 'utf8').replaceAll(String.fromCharCode(13), '');
  const fm = /^---\n([\s\S]*?)\n---/.exec(t);
  if (!fm || !/^name:\s*\S+/m.test(fm[1]) || !/^description:\s*\S+/m.test(fm[1])) fail('skills', `${d}/SKILL.md needs name + description front-matter`);
  else if (fm[1].match(/^name:\s*(\S+)/m)[1] !== d) fail('skills', `${d}/SKILL.md name does not match its folder`);
}

// 3b ── skill folders mirrored in FLAT-LIBRARY must not contradict (just report duplicates)
// 4 ── stale references to things that were removed or never belonged here
// Optional local blocklist: one regex per line in .audit-blocklist (git-ignored) for names that must never appear.
const STALE = existsSync(join(root, '.audit-blocklist'))
  ? new RegExp(readFileSync(join(root, '.audit-blocklist'), 'utf8').split(String.fromCharCode(10)).map((l) => l.trim()).filter(Boolean).join('|'), 'i')
  : /$^/;
for (const f of byExt(/\.(md|m?js|json|py|html)$/)) {
  if (rel(f).startsWith('scripts/audit.mjs')) continue;
  const text = readFileSync(f, 'utf8');
  const m = STALE.exec(text);
  if (m) fail('stale', `${rel(f)} mentions "${m[0]}"`);
}

// 5 ── MCP bridge loads
const bridge = join(root, 'SHADDAI-MCP-BRIDGE', 'mcp.js');
if (existsSync(bridge)) {
  const r = spawnSync(process.execPath, ['-e', `try{require(${JSON.stringify(bridge)});console.log('ok')}catch(e){console.log('ERR '+e.message)}`], { encoding: 'utf8', timeout: 20000 });
  if (!/^ok/.test(r.stdout || '')) fail('bridge', `mcp.js does not load: ${(r.stdout || r.stderr).trim().slice(0, 160)}`);
  else notes.push('MCP bridge loads');
}

// 6 ── tests
function tests(label, cmd, args, cwd) {
  const r = spawnSync(cmd, args, { cwd, encoding: 'utf8', timeout: 300000 });
  const out = `${r.stdout || ''}${r.stderr || ''}`;
  if (r.status !== 0) fail('tests', `${label} failed:\n${out.trim().split('\n').slice(-8).join('\n')}`);
  else notes.push(`${label}: ${(out.match(/(\d+ passed)|(all [\w ]+ tests passed)/i) || ['ok'])[0]}`);
}
const gf = join(root, 'game-forge');
for (const t of ['ecs/world.test.mjs', 'runtime/runtime.test.mjs', 'runtime/panorama.test.mjs']) if (existsSync(join(gf, t))) tests(t, process.execPath, [t], gf);
if (existsSync(join(root, 'vision', 'vision.test.mjs'))) tests('vision/vision.test.mjs', process.execPath, ['vision/vision.test.mjs'], root);
const atelier = join(root, 'shaddai-3d-atelier');
if (existsSync(atelier)) tests('atelier pytest', 'python', ['-m', 'pytest', '-q', '-p', 'no:cacheprovider'], atelier);

// 7 ── guides are indexed in the Game Forge README
const guides = readdirSync(join(gf, 'guides')).filter((f) => /^\d\d-/.test(f));
const readme = readFileSync(join(gf, 'README.md'), 'utf8');
if (!new RegExp(`01.${String(guides.length).padStart(2, '0')}`).test(readme)) fail('docs', `game-forge/README.md should say guides 01–${String(guides.length).padStart(2, '0')}`);

console.log(notes.map((n) => '  ✓ ' + n).join('\n'));
if (problems.length) { console.log(`\n${problems.length} problem(s):\n` + problems.map((p) => '  ✗ ' + p).join('\n')); process.exit(1); }
console.log('\nAUDIT PASSED');

