import assert from 'node:assert/strict';
import { dirFromAngles, anglesFromDir, dirToEquirect, equirectToDir, cubeFaceDir, dirToCubeFace,
         FACES, detectLayout, bilinear, equirectToCubeFace, sample, FILTERS, crossToFaces, facesToCross, cubeToEquirect } from './panorama.mjs';

const test = (name, fn) => { fn(); console.log('ok  ' + name); };
const near = (a, b, eps = 1e-9) => assert.ok(Math.abs(a - b) < eps, `${a} !≈ ${b}`);

test('yaw 0 looks down -Z; positive yaw turns right; pitch up is +Y', () => {
  const f = dirFromAngles(0, 0); near(f.z, -1); near(f.x, 0);
  near(dirFromAngles(Math.PI / 2, 0).x, 1);
  near(dirFromAngles(0, Math.PI / 2).y, 1);
});

test('angles round-trip', () => {
  for (const [yaw, pitch] of [[0.3, 0.2], [-2.5, -1.0], [3, 1.4]]) {
    const r = anglesFromDir(dirFromAngles(yaw, pitch)); near(r.yaw, yaw); near(r.pitch, pitch);
  }
});

test('equirect: centre is forward, top row is up, round-trips', () => {
  const c = dirToEquirect({ x: 0, y: 0, z: -1 }); near(c.u, 0.5); near(c.v, 0.5);
  near(dirToEquirect({ x: 0, y: 1, z: 0 }).v, 0);
  for (const [u, v] of [[0.1, 0.3], [0.9, 0.8], [0.5, 0.5]]) {
    const r = dirToEquirect(equirectToDir(u, v)); near(r.u, u, 1e-9); near(r.v, v, 1e-9);
  }
});

test('cube faces: every direction lands on the face whose axis it points along', () => {
  const axes = { px: [1, 0, 0], nx: [-1, 0, 0], py: [0, 1, 0], ny: [0, -1, 0], pz: [0, 0, 1], nz: [0, 0, -1] };
  for (const f of FACES) {
    const r = dirToCubeFace({ x: axes[f][0], y: axes[f][1], z: axes[f][2] });
    assert.equal(r.face, f); near(r.s, 0); near(r.t, 0);
  }
});

test('cube faces: dir → face → dir round-trips (direction preserved)', () => {
  for (const d of [{ x: 0.3, y: 0.2, z: -0.9 }, { x: -0.8, y: 0.1, z: 0.2 }, { x: 0.1, y: -0.9, z: 0.3 }]) {
    const { face, s, t } = dirToCubeFace(d), back = cubeFaceDir(face, s, t);
    const k = Math.hypot(d.x, d.y, d.z) / Math.hypot(back.x, back.y, back.z);
    near(back.x * k, d.x); near(back.y * k, d.y); near(back.z * k, d.z);
  }
});

test('layout detection', () => {
  assert.equal(detectLayout(2048, 1024), 'equirect');
  assert.equal(detectLayout(1024, 768), 'cube-cross');
  assert.equal(detectLayout(6144, 1024), 'cube-strip-h');
  assert.equal(detectLayout(1024, 6144), 'cube-strip-v');
  assert.equal(detectLayout(1000, 900), null);
});

test('bilinear blends neighbours', () => {
  const img = { width: 2, height: 1, data: new Uint8ClampedArray([0, 0, 0, 255, 200, 100, 50, 255]) };
  const mid = bilinear(img, 0.5, 0.5);
  near(mid[0], 100, 1e-6); near(mid[3], 255, 1e-6);
});

test('equirect → cube face: forward face centre samples the image centre', () => {
  const w = 64, h = 32, data = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) data.set([x * 4, y * 8, 0, 255], (y * w + x) * 4);
  const face = equirectToCubeFace({ width: w, height: h, data }, 'nz', 8);   // nz = forward (-Z)
  const centre = (4 * 8 + 4) * 4;
  assert.ok(Math.abs(face.data[centre] - 126) < 12, 'u should be near the image middle, got ' + face.data[centre]);
  assert.ok(Math.abs(face.data[centre + 1] - 124) < 12);
});

test('cross layout: faces → cross → faces is lossless, and rejects wrong shapes', () => {
  const size = 4, faces = {};
  FACES.forEach((f, k) => { const d = new Uint8ClampedArray(size * size * 4).fill(10 * (k + 1)); faces[f] = { width: size, height: size, data: d }; });
  const cross = facesToCross(faces);
  assert.equal(detectLayout(cross.width, cross.height), 'cube-cross');
  const back = crossToFaces(cross);
  for (const f of FACES) assert.deepEqual(Array.from(back[f].data), Array.from(faces[f].data));
  assert.throws(() => crossToFaces({ width: 8, height: 4, data: new Uint8ClampedArray(128) }));
});

test('equirect → cube → equirect keeps the picture (smooth gradient, small error)', () => {
  const w = 128, h = 64, data = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) data.set([Math.round(255 * x / w), Math.round(255 * y / h), 80, 255], (y * w + x) * 4);
  const src = { width: w, height: h, data };
  const faces = Object.fromEntries(FACES.map((f) => [f, equirectToCubeFace(src, f, 64)]));
  const out = cubeToEquirect(faces, w, h);
  let worst = 0;
  for (let y = 8; y < h - 8; y++) for (let x = 4; x < w - 4; x++) for (let c = 0; c < 2; c++) {
    worst = Math.max(worst, Math.abs(out.data[(y * w + x) * 4 + c] - src.data[(y * w + x) * 4 + c]));
  }
  assert.ok(worst < 12, 'worst channel error ' + worst);
});

const ramp = (w, h) => { const d = new Uint8ClampedArray(w * h * 4); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) d.set([x * 10, y * 10, 5, 255], (y * w + x) * 4); return { width: w, height: h, data: d }; };

test('every filter returns the exact pixel at a pixel centre', () => {
  const img = ramp(8, 8);
  for (const filter of FILTERS) {
    const px = sample(img, (3 + 0.5) / 8, (4 + 0.5) / 8, { filter });
    near(px[0], 30, 1e-6); near(px[1], 40, 1e-6);
  }
});

test('bicubic and lanczos reproduce a linear ramp between pixels; nearest steps', () => {
  const img = ramp(16, 16);
  for (const filter of ['bilinear', 'bicubic', 'lanczos']) near(sample(img, (6 + 0.5 + 0.5) / 16, 0.5, { filter })[0], 65, 0.6);
  assert.equal(sample(img, (6 + 1.1) / 16, 0.5, { filter: 'nearest' })[0], 70);
});

test('wrapU blends across the 360° seam instead of clamping', () => {
  const w = 8, d = new Uint8ClampedArray(w * 4 * 4);
  for (let y = 0; y < 4; y++) for (let x = 0; x < w; x++) d.set([x === 0 ? 200 : 0, 0, 0, 255], (y * w + x) * 4);
  const img = { width: w, height: 4, data: d };
  const clamped = sample(img, 1, 0.5, { filter: 'bilinear' })[0];                  // right edge, no wrap: last column only
  const wrapped = sample(img, 1, 0.5, { filter: 'bilinear', wrapU: true })[0];     // halfway between last and first column
  near(clamped, 0, 1e-6); near(wrapped, 100, 1e-6);
});

test('unknown filter is rejected', () => assert.throws(() => sample(ramp(2, 2), 0.5, 0.5, { filter: 'magic' })));

console.log('all panorama tests passed');

// SHADDAI Game Forge — ECS "World". Original implementation (NEXUS).
//
// Model
//   • An entity is an integer handle: low 20 bits = slot, high bits = generation,
//     so a recycled slot never answers to an old handle.
//   • Components live in per-type sparse sets (dense arrays + a slot→index map):
//     iteration is a straight array walk, add/remove is O(1).
//   • A query is a set of component types. Results are cached and invalidated only
//     when a matching component is added or removed.
//   • Structural changes made while systems run are queued and applied between
//     systems, so nothing mutates under an active loop.
//
// Usage
//   const world = new World();
//   const Pos = world.define('pos'), Vel = world.define('vel');
//   const e = world.spawn({ pos: { x: 0, y: 0 }, vel: { x: 1, y: 0 } });
//   world.system('move', ['pos', 'vel'], (e, { pos, vel }, dt) => { pos.x += vel.x * dt; });
//   world.step(1 / 60);

const SLOT_BITS = 20;
const SLOT_MASK = (1 << SLOT_BITS) - 1;

class SparseSet {
  constructor() { this.dense = []; this.owners = []; this.index = new Map(); }
  has(slot) { return this.index.has(slot); }
  get(slot) { const i = this.index.get(slot); return i === undefined ? undefined : this.dense[i]; }
  set(slot, value) {
    const i = this.index.get(slot);
    if (i !== undefined) { this.dense[i] = value; return false; }
    this.index.set(slot, this.dense.length); this.dense.push(value); this.owners.push(slot);
    return true;
  }
  delete(slot) {
    const i = this.index.get(slot);
    if (i === undefined) return false;
    const last = this.dense.length - 1;
    if (i !== last) {                       // swap-remove keeps the arrays dense
      this.dense[i] = this.dense[last]; this.owners[i] = this.owners[last]; this.index.set(this.owners[i], i);
    }
    this.dense.pop(); this.owners.pop(); this.index.delete(slot);
    return true;
  }
}

export class World {
  constructor() {
    this.stores = new Map();        // type name → SparseSet
    this.generation = [];           // slot → current generation
    this.alive = [];                // slot → boolean
    this.free = [];                 // recycled slots
    this.queries = new Map();       // key → { types, slots, dirty }
    this.systems = [];              // { name, types, fn, phase }
    this.phases = ['early', 'update', 'late'];
    this.pending = [];              // deferred structural ops
    this.running = false;
    this.listeners = new Map();     // event → Set<fn>
    this.time = 0;
  }

  // ── types ──────────────────────────────────────────────────────────────────
  define(type) { if (!this.stores.has(type)) this.stores.set(type, new SparseSet()); return type; }

  // ── entities ───────────────────────────────────────────────────────────────
  spawn(components = {}) {
    const slot = this.free.length ? this.free.pop() : this.generation.length;
    if (slot > SLOT_MASK) throw new Error('entity limit reached');
    if (slot === this.generation.length) { this.generation.push(0); this.alive.push(false); }
    this.alive[slot] = true;
    const handle = (this.generation[slot] << SLOT_BITS) | slot;
    for (const [type, value] of Object.entries(components)) this.#put(slot, type, value);
    return handle;
  }
  isAlive(handle) {
    const slot = handle & SLOT_MASK;
    return this.alive[slot] === true && this.generation[slot] === (handle >>> SLOT_BITS);
  }
  despawn(handle) {
    if (this.running) return void this.pending.push(() => this.despawn(handle));
    if (!this.isAlive(handle)) return;
    const slot = handle & SLOT_MASK;
    for (const [type, store] of this.stores) if (store.delete(slot)) this.#touch(type);
    this.alive[slot] = false; this.generation[slot]++; this.free.push(slot);
  }

  // ── components ─────────────────────────────────────────────────────────────
  add(handle, type, value = {}) {
    if (this.running) return void this.pending.push(() => this.add(handle, type, value));
    if (this.isAlive(handle)) this.#put(handle & SLOT_MASK, type, value);
  }
  remove(handle, type) {
    if (this.running) return void this.pending.push(() => this.remove(handle, type));
    const store = this.stores.get(type);
    if (store && this.isAlive(handle) && store.delete(handle & SLOT_MASK)) this.#touch(type);
  }
  get(handle, type) { return this.isAlive(handle) ? this.stores.get(type)?.get(handle & SLOT_MASK) : undefined; }
  has(handle, type) { return this.isAlive(handle) && !!this.stores.get(type)?.has(handle & SLOT_MASK); }

  #put(slot, type, value) {
    this.define(type);
    if (this.stores.get(type).set(slot, value)) this.#touch(type);
  }
  #touch(type) { for (const q of this.queries.values()) if (q.types.includes(type)) q.dirty = true; }

  // ── queries ────────────────────────────────────────────────────────────────
  // Returns live entity handles that have every listed component.
  query(types) {
    const key = [...types].sort().join('|');
    let q = this.queries.get(key);
    if (!q) { q = { types: [...types], slots: [], dirty: true }; this.queries.set(key, q); }
    if (q.dirty) {
      const stores = types.map((t) => this.stores.get(t));
      if (stores.some((s) => !s)) q.slots = [];
      else {
        const smallest = stores.reduce((a, b) => (a.owners.length <= b.owners.length ? a : b));
        q.slots = smallest.owners.filter((slot) => stores.every((s) => s.has(slot)));
      }
      q.dirty = false;
    }
    return q.slots.map((slot) => (this.generation[slot] << SLOT_BITS) | slot);
  }

  // ── systems ────────────────────────────────────────────────────────────────
  system(name, types, fn, phase = 'update') {
    if (!this.phases.includes(phase)) throw new Error('unknown phase: ' + phase);
    this.systems.push({ name, types, fn, phase });
    return this;
  }
  step(dt) {
    this.time += dt;
    this.running = true;
    try {
      for (const phase of this.phases) {
        for (const sys of this.systems) {
          if (sys.phase !== phase) continue;
          for (const e of this.query(sys.types)) {
            const parts = {};
            for (const t of sys.types) parts[t] = this.stores.get(t).get(e & SLOT_MASK);
            sys.fn(e, parts, dt, this);
          }
          this.#flush();
        }
      }
    } finally { this.running = false; this.#flush(); }
  }
  #flush() {
    const ops = this.pending; this.pending = [];
    const was = this.running; this.running = false;
    for (const op of ops) op();
    this.running = was;
  }

  // ── events ─────────────────────────────────────────────────────────────────
  on(event, fn) { (this.listeners.get(event) ?? this.listeners.set(event, new Set()).get(event)).add(fn); return () => this.listeners.get(event).delete(fn); }
  emit(event, payload) { for (const fn of this.listeners.get(event) ?? []) fn(payload); }
}

// Turns a capture report into findings: what is wrong, the evidence, and where in the code to look.
//
// report = {
//   frames:  [{ t, metrics, diffFromPrevious }],            // diffFromPrevious: changedPercent or null
//   console: [{ type, text }],                              // browser console + uncaught errors
//   failedRequests: [{ url, status }],
//   perf:    { fps, p95FrameMs, maxFrameMs, drawCalls, triangles },   // any field may be null
//   inputsSent: number
// }

const F = (severity, id, title, evidence, look, fix) => ({ severity, id, title, evidence, lookAt: look, hint: fix });

export function analyze(report) {
  const out = [];
  const frames = report.frames || [], perf = report.perf || {};
  const blank = (m) => m.std < 2 && (m.darkFraction > 0.97 || m.brightFraction > 0.97);

  if (frames.length) {
    const blanks = frames.filter((f) => blank(f.metrics));
    if (blanks.length === frames.length) {
      out.push(F('critical', 'nothing-drawn', 'Nothing is visible — every frame is blank',
        `${frames.length}/${frames.length} frames are a single flat colour`,
        ['guides/01-scene-and-renderer.md', 'guides/03-cameras-and-feel.md'],
        'Check: renderer.domElement added to the page; canvas has non-zero size; camera is not inside or facing away from the scene; lights exist for lit materials; the render loop actually runs; objects were added to the scene.'));
    } else if (blanks.length) {
      out.push(F('warning', 'blank-frames', 'Some frames are blank',
        `blank at t=${blanks.map((f) => f.t).join(', ')}s`, ['guides/02-game-loop.md', 'guides/04-assets-and-materials.md'],
        'Look for scene changes (level loads, restarts) that clear the canvas, or assets that appear late.'));
    } else {
      const flat = frames.every((f) => f.metrics.std < 20);
      if (flat) out.push(F('warning', 'flat-image', 'The image is very flat — almost no contrast',
        `luminance spread (std) is ${Math.max(...frames.map((f) => f.metrics.std))} or less in every frame`,
        ['guides/04-assets-and-materials.md', 'guides/15-postprocessing.md'], 'Add a key light plus fill, separate foreground from background by value, and check fog/ambient are not washing everything out.'));
      if (frames.every((f) => f.metrics.colourRatio < 0.01)) out.push(F('info', 'few-colours', 'Very few distinct colours — looks like placeholder art',
        `colour ratio below 1% in every frame`, ['guides/04-assets-and-materials.md'], 'Introduce a palette with an accent colour, texture or gradient the key objects, and vary the background.'));
      const m = frames.map((f) => f.metrics.mean);
      if (Math.min(...m) > 200 && frames.every((f) => f.metrics.brightFraction > 0.4)) out.push(F('warning', 'overexposed', 'The scene is overexposed', `mean brightness ${Math.min(...m)}+`, ['guides/04-assets-and-materials.md', 'guides/15-postprocessing.md'], 'Lower light intensity, enable tone mapping, reduce emissive/ambient.'));
      if (Math.max(...m) < 40) out.push(F('warning', 'underexposed', 'The scene is too dark to read', `mean brightness ${Math.max(...m)} or less`, ['guides/04-assets-and-materials.md'], 'Add a fill/hemisphere light or an environment map; check material colours are not near black.'));
      const moving = frames.filter((f) => f.diffFromPrevious != null);
      if (moving.length >= 3 && moving.every((f) => f.diffFromPrevious < 0.05)) {
        out.push(F(report.inputsSent ? 'critical' : 'warning', 'frozen', 'The picture never changes',
          `${moving.length} consecutive captures differ by under 0.05%` + (report.inputsSent ? ` even though ${report.inputsSent} inputs were sent` : ''),
          ['guides/02-game-loop.md', 'guides/14-interaction-and-controls.md'],
          report.inputsSent ? 'Inputs are not reaching the game: check key/pointer listeners, canvas focus, and that the simulation actually steps.' : 'Nothing is moving: confirm the loop runs and that something animates (idle motion helps a game feel alive).'));
      }
    }
  }

  const cv = report.canvas;
  if (cv) {
    if (cv.w < 2 || cv.h < 2) out.push(F('critical', 'canvas-zero-size', 'The canvas has no size', `canvas is ${Math.round(cv.w)}x${Math.round(cv.h)}`, ['guides/01-scene-and-renderer.md'], 'Set the canvas width/height (or CSS size) and call renderer.setSize before the first render.'));
    else {
      const cover = (cv.w * cv.h) / (cv.vw * cv.vh);
      if (cover < 0.8) out.push(F('warning', 'canvas-not-filling-window', 'The game does not fill the window',
        `canvas is ${Math.round(cv.w)}x${Math.round(cv.h)} in a ${cv.vw}x${cv.vh} window (${Math.round(cover * 100)}% of it)`, ['guides/01-scene-and-renderer.md', 'guides/14-interaction-and-controls.md'],
        'Size the canvas to the viewport (100vw x 100vh, body margin 0), call renderer.setSize and update camera.aspect on resize, and check devicePixelRatio handling. If a fixed size is intentional, centre it and style the surround.'));
    }
  }
  const errors = (report.console || []).filter((c) => c.type === 'error' || c.type === 'pageerror');
  if (errors.length) out.push(F('critical', 'console-errors', `${errors.length} console error${errors.length > 1 ? 's' : ''}`,
    errors.slice(0, 3).map((e) => e.text.slice(0, 140)).join(' | '), ['the file and line named in the first error'], 'Fix the first error first — later ones are often caused by it.'));
  const warns = (report.console || []).filter((c) => c.type === 'warning');
  if (warns.length) out.push(F('info', 'console-warnings', `${warns.length} console warning${warns.length > 1 ? 's' : ''}`, warns.slice(0, 2).map((e) => e.text.slice(0, 120)).join(' | '), [], 'Warnings often point at deprecated APIs or wrong colour-space/texture settings.'));
  if ((report.failedRequests || []).length) out.push(F('critical', 'missing-assets', `${report.failedRequests.length} request(s) failed`,
    report.failedRequests.slice(0, 3).map((r) => `${r.status} ${r.url}`).join(' | '), ['guides/04-assets-and-materials.md'], 'Fix paths and casing, confirm files are served, and show a visible fallback while loading.'));

  if (perf.fps != null) {
    if (perf.fps < 30) out.push(F('critical', 'low-fps', `Frame rate is ${perf.fps} fps`, `p95 frame ${perf.p95FrameMs} ms`, ['guides/09-performance.md'], 'Find the bottleneck first: shrink the window (fill-rate?) and check draw calls (CPU?) before changing anything.'));
    else if (perf.fps < 50) out.push(F('warning', 'low-fps', `Frame rate is ${perf.fps} fps — below the 60 fps target`, `p95 frame ${perf.p95FrameMs} ms`, ['guides/09-performance.md'], 'Cap pixel ratio, share materials, instance repeats, reduce shadow cost.'));
    if (perf.maxFrameMs > 100) out.push(F('warning', 'frame-spikes', `Frame spikes up to ${perf.maxFrameMs} ms`, 'single frames take over 100 ms', ['guides/09-performance.md', 'guides/04-assets-and-materials.md'], 'Spikes usually mean per-frame allocations (garbage collection), shader compiles on first use, or texture uploads. Pre-warm and pool.'));
  }
  if (perf.drawCalls > 300) out.push(F('warning', 'many-draw-calls', `${perf.drawCalls} draw calls per frame`, 'budget is about 300', ['guides/09-performance.md', 'guides/13-geometry-and-textures.md'], 'Merge static geometry, share materials, use InstancedMesh for repeats.'));
  if (perf.triangles > 1500000) out.push(F('warning', 'heavy-geometry', `${perf.triangles} triangles per frame`, 'over 1.5M', ['guides/09-performance.md'], 'Add LOD, cull distant objects, decimate hero assets.'));

  const rank = { critical: 0, warning: 1, info: 2 };
  return out.sort((a, b) => rank[a.severity] - rank[b.severity]);
}

export function summarize(findings) {
  if (!findings.length) return 'No issues detected by the automatic checks. Look at the screenshots anyway — these checks cannot judge taste.';
  return findings.map((f, i) => `${i + 1}. [${f.severity.toUpperCase()}] ${f.title}\n   evidence: ${f.evidence}\n   look at: ${f.lookAt.join(', ') || '—'}\n   hint: ${f.hint}`).join('\n');
}

// Panorama and skybox maths (NEXUS) — pure functions, no dependencies, usable in Node and the browser.
//
// Conventions (match three.js): right-handed, +X right, +Y up, camera looks down -Z at yaw 0.
//   yaw   0 → forward, positive turns right.   pitch +π/2 → straight up.
//   Image coordinates: u 0→1 left→right, v 0→1 top→bottom.
// Cube faces use the standard graphics-API layout: 'px','nx','py','ny','pz','nz', with (s,t) in [-1,1],
// s to the right and t downward when the face is viewed from inside.

const TAU = Math.PI * 2;

export function dirFromAngles(yaw, pitch) {
  const c = Math.cos(pitch);
  return { x: Math.sin(yaw) * c, y: Math.sin(pitch), z: -Math.cos(yaw) * c };
}

export function anglesFromDir({ x, y, z }) {
  const len = Math.hypot(x, y, z) || 1;
  return { yaw: Math.atan2(x, -z), pitch: Math.asin(y / len) };
}

// ── equirectangular (2:1 sphere map) ────────────────────────────────────────
export function dirToEquirect(dir) {
  const { yaw, pitch } = anglesFromDir(dir);
  return { u: 0.5 + yaw / TAU, v: 0.5 - pitch / Math.PI };
}
export function equirectToDir(u, v) {
  return dirFromAngles((u - 0.5) * TAU, (0.5 - v) * Math.PI);
}

// ── cube faces ──────────────────────────────────────────────────────────────
export const FACES = ['px', 'nx', 'py', 'ny', 'pz', 'nz'];

export function cubeFaceDir(face, s, t) {
  switch (face) {
    case 'px': return { x: 1, y: -t, z: -s };
    case 'nx': return { x: -1, y: -t, z: s };
    case 'py': return { x: s, y: 1, z: t };
    case 'ny': return { x: s, y: -1, z: -t };
    case 'pz': return { x: s, y: -t, z: 1 };
    case 'nz': return { x: -s, y: -t, z: -1 };
    default: throw new Error('unknown cube face: ' + face);
  }
}

export function dirToCubeFace({ x, y, z }) {
  const ax = Math.abs(x), ay = Math.abs(y), az = Math.abs(z);
  let face, s, t, m;
  if (ax >= ay && ax >= az) { m = ax; face = x > 0 ? 'px' : 'nx'; s = x > 0 ? -z : z; t = -y; }
  else if (ay >= az) { m = ay; face = y > 0 ? 'py' : 'ny'; s = x; t = y > 0 ? z : -z; }
  else { m = az; face = z > 0 ? 'pz' : 'nz'; s = z > 0 ? x : -x; t = -y; }
  return { face, s: s / m, t: t / m };
}

// ── layouts ─────────────────────────────────────────────────────────────────
// Guess what an image is from its size. Returns null when it matches nothing.
export function detectLayout(width, height) {
  const r = width / height;
  const near = (a) => Math.abs(r - a) < 0.02;
  if (near(2)) return 'equirect';          // 2:1 sphere map
  if (near(4 / 3)) return 'cube-cross';    // 4×3 unfolded cube
  if (near(6)) return 'cube-strip-h';      // six faces side by side
  if (near(1 / 6)) return 'cube-strip-v';  // six faces stacked
  return null;
}

// ── resampling ──────────────────────────────────────────────────────────────
// image: { width, height, data: Uint8ClampedArray RGBA }
// Reconstruction kernels: [radius in pixels, weight(distance)].
//   bilinear — tent;  bicubic — Catmull-Rom (exact on linear ramps);  lanczos — sinc windowed to 3 lobes.
const KERNELS = {
  nearest: null,
  bilinear: [1, (d) => Math.max(0, 1 - Math.abs(d))],
  bicubic: [2, (d) => {
    d = Math.abs(d);
    return d < 1 ? 1.5 * d ** 3 - 2.5 * d * d + 1 : d < 2 ? -0.5 * d ** 3 + 2.5 * d * d - 4 * d + 2 : 0;
  }],
  lanczos: [3, (d) => {
    d = Math.abs(d);
    if (d === 0) return 1;
    if (d >= 3) return 0;
    const p = Math.PI * d;
    return (3 * Math.sin(p) * Math.sin(p / 3)) / (p * p);
  }],
};
export const FILTERS = Object.keys(KERNELS);

const wrap = (i, n) => ((i % n) + n) % n;
const clampIdx = (i, n) => (i < 0 ? 0 : i > n - 1 ? n - 1 : i);

// Sample an RGBA image at (u,v) in [0,1]². Pixel centres sit at half-integers, so there is no
// half-pixel drift. `wrapU` wraps horizontally — required for 360° images, otherwise the seam
// behind the viewer blurs against the opposite edge instead of the neighbouring column.
export function sample(image, u, v, { filter = 'bilinear', wrapU = false } = {}) {
  const { width: w, height: h, data } = image;
  const px = u * w - 0.5, py = v * h - 0.5, out = [0, 0, 0, 0];
  const col = (i) => (wrapU ? wrap(i, w) : clampIdx(i, w));
  const k = KERNELS[filter];
  if (k === undefined) throw new Error('unknown filter: ' + filter);
  if (k === null) {
    const o = (clampIdx(Math.round(py), h) * w + col(Math.round(px))) * 4;
    return [data[o], data[o + 1], data[o + 2], data[o + 3]];
  }
  const [r, weight] = k, x0 = Math.floor(px), y0 = Math.floor(py);
  const wx = [], wy = [];
  let sx = 0, sy = 0;
  for (let t = 1 - r; t <= r; t++) {
    const a = weight(px - (x0 + t)), b = weight(py - (y0 + t));
    wx.push(a); wy.push(b); sx += a; sy += b;
  }
  for (let j = 0; j < 2 * r; j++) {
    const row = clampIdx(y0 + 1 - r + j, h) * w;
    for (let i = 0; i < 2 * r; i++) {
      const o = (row + col(x0 + 1 - r + i)) * 4, f = (wx[i] / sx) * (wy[j] / sy);
      out[0] += data[o] * f; out[1] += data[o + 1] * f; out[2] += data[o + 2] * f; out[3] += data[o + 3] * f;
    }
  }
  return out;
}

export const bilinear = (image, u, v, opts) => sample(image, u, v, { ...opts, filter: 'bilinear' });

// Render one cube face (size×size RGBA) from an equirectangular image.
export function equirectToCubeFace(image, face, size, { filter = 'bilinear' } = {}) {
  const data = new Uint8ClampedArray(size * size * 4);
  for (let j = 0; j < size; j++) {
    for (let i = 0; i < size; i++) {
      const s = ((i + 0.5) / size) * 2 - 1, t = ((j + 0.5) / size) * 2 - 1;
      const { u, v } = dirToEquirect(cubeFaceDir(face, s, t));
      data.set(sample(image, u, v, { filter, wrapU: true }), (j * size + i) * 4);
    }
  }
  return { width: size, height: size, data };
}

// ── cube ↔ equirect and the 4×3 cross ──────────────────────────────────────
// Cross layout (cells are `size` px):        [  ][py][  ][  ]
//                                            [nx][pz][px][nz]
//                                            [  ][ny][  ][  ]
const CROSS_CELL = { py: [1, 0], nx: [0, 1], pz: [1, 1], px: [2, 1], nz: [3, 1], ny: [1, 2] };

function cropRect(image, x0, y0, w, h) {
  const out = new Uint8ClampedArray(w * h * 4);
  for (let y = 0; y < h; y++) {
    const from = ((y0 + y) * image.width + x0) * 4;
    out.set(image.data.subarray(from, from + w * 4), y * w * 4);
  }
  return { width: w, height: h, data: out };
}

// Split a 4:3 cross image into six face images.
export function crossToFaces(image) {
  if (detectLayout(image.width, image.height) !== 'cube-cross') throw new Error('not a 4:3 cross layout');
  const size = image.width / 4, faces = {};
  for (const f of FACES) { const [cx, cy] = CROSS_CELL[f]; faces[f] = cropRect(image, cx * size, cy * size, size, size); }
  return faces;
}

// Pack six equal square faces into a 4:3 cross (unused cells stay transparent).
export function facesToCross(faces) {
  const size = faces.px.width, width = size * 4, height = size * 3;
  const data = new Uint8ClampedArray(width * height * 4);
  for (const f of FACES) {
    const [cx, cy] = CROSS_CELL[f];
    for (let y = 0; y < size; y++) data.set(faces[f].data.subarray(y * size * 4, (y + 1) * size * 4), ((cy * size + y) * width + cx * size) * 4);
  }
  return { width, height, data };
}

// Rebuild a 2:1 sphere map from six faces.
export function cubeToEquirect(faces, width, height = width / 2, { filter = 'bilinear' } = {}) {
  const data = new Uint8ClampedArray(width * height * 4);
  for (let j = 0; j < height; j++) {
    for (let i = 0; i < width; i++) {
      const { face, s, t } = dirToCubeFace(equirectToDir((i + 0.5) / width, (j + 0.5) / height));
      data.set(sample(faces[face], (s + 1) / 2, (t + 1) / 2, { filter }), (j * width + i) * 4);
    }
  }
  return { width, height, data };
}

/**
 * TURTLE Agent Interface
 *
 * TURTLE is SHADDAI's UI/UX + Design + Frontend specialist.
 * This interface gives TURTLE direct access to all game-dev skills & templates.
 *
 * TURTLE commands:
 * - "Build me a 2D platformer scaffold"
 * - "Show me how to use advanced shaders"
 * - "Create a 3D action game from scratch"
 */

const mcp = require('./mcp')
const fs = require('fs')
const path = require('path')

/**
 * Parse natural language commands from TURTLE
 */
function parseCommand(input) {
  const lowerInput = input.toLowerCase()

  // Pattern: "build me a [genre] scaffold"
  const buildMatch = input.match(/build.*(?:me\s+)?a\s+([a-z0-9\-\s]+)\s+(?:scaffold|game|project)/i)
  if (buildMatch) {
    return {
      action: 'build-scaffold',
      genre: buildMatch[1].trim().replace(/\s+/g, '-'),
      confidence: 0.95
    }
  }

  // Pattern: "show me [skill]" or "how do I [skill]"
  const skillMatch = input.match(/(?:show|teach|explain).*?(?:how to|the)\s+([a-z0-9\-\s]+)/i)
  if (skillMatch) {
    const skillName = skillMatch[1].trim().replace(/\s+/g, '-').replace(/^the-/, '')
    return {
      action: 'explain-skill',
      skill: `threejs-${skillName}`,
      confidence: 0.85
    }
  }

  // Pattern: "search for [pattern]"
  const searchMatch = input.match(/search.*?(?:for|patterns?)\s+(.+?)(?:\?|$)/i)
  if (searchMatch) {
    return {
      action: 'search-pattern',
      query: searchMatch[1].trim(),
      confidence: 0.9
    }
  }

  return {
    action: 'unknown',
    confidence: 0
  }
}

/**
 * Execute TURTLE command
 */
function executeTurtleCommand(command) {
  switch (command.action) {
    case 'build-scaffold':
      return buildScaffold(command.genre)

    case 'explain-skill':
      return explainSkill(command.skill)

    case 'search-pattern':
      return searchPatterns(command.query)

    default:
      return {
        error: 'Command not understood',
        hint: 'Try: "Build me a 3D action game", "Show me shaders", "Search for physics"'
      }
  }
}

/**
 * Build a game scaffold from a genre template
 */
function buildScaffold(genre) {
  const genres = mcp.listGenres()
  const genreMatch = genres.find(g => g.name.includes(genre.replace(/-/g, '')))

  if (!genreMatch) {
    return {
      error: `Genre not found: ${genre}`,
      available: genres.map(g => g.name)
    }
  }

  const scaffold = mcp.getGenreScaffold(genreMatch.name)
  if (scaffold.error) return scaffold

  // Add TURTLE-specific metadata
  return {
    genre: genreMatch.name,
    scaffold: scaffold,
    turtleInstructions: `
# ${genreMatch.name.toUpperCase()} Game Scaffold

1. **Copy scaffold structure**: \`${scaffold.scaffoldPath}\` → your project folder
2. **Follow architecture docs**: Read \`docs/architecture.md\`
3. **Run example**: Check \`examples/\` for reference implementation
4. **Customize systems**: Edit \`systems/\` for your game logic
5. **Test performance**: Use \`/game-qa-performance\` skill

## Key files to modify:
- \`main.js\` - Entry point
- \`systems/\` - Game logic
- \`scenes/\` - Level/scene management
- \`assets/\` - Models, textures, audio

## Quick start:
\`\`\`bash
cd ${genreMatch.name}-game
npm install
npm run dev
\`\`\`
    `,
    designTips: getTurtleDesignTips(genreMatch.name),
    estimatedTime: '2-4 hours to customize'
  }
}

/**
 * Explain a Three.js skill in TURTLE's style
 */
function explainSkill(skillName) {
  const skills = mcp.listSkills()
  const skillMatch = skills.find(s => s.name.toLowerCase().includes(skillName.toLowerCase()))

  if (!skillMatch) {
    return {
      error: `Skill not found: ${skillName}`,
      available: skills.map(s => s.name)
    }
  }

  const skillPath = path.join(mcp.SKILLS_DIR, skillMatch.name, 'SKILL.md')
  const content = fs.readFileSync(skillPath, 'utf8')

  return {
    skill: skillMatch.name,
    documentation: content,
    turtleContext: `
This is a ${skillMatch.description}.

**For your designs:**
- Use this when building interactive 3D scenes
- Great for prototyping game mechanics visually
- Works in real-time browser, perfect for iteration

**Time to learn:** 30 min - 1 hour
**Complexity:** Medium
**Dependencies:** Three.js, basic JavaScript
    `,
    relatedSkills: getRelatedSkills(skillMatch.name),
    examples: findSkillExamples(skillMatch.name)
  }
}

/**
 * Search the flat library for patterns
 */
function searchPatterns(query) {
  const results = mcp.searchFlatLibrary(query)

  if (results.length === 0) {
    return {
      message: `No patterns found for "${query}"`,
      suggestion: 'Try broader terms: "physics", "camera", "particles", "lighting"'
    }
  }

  return {
    query: query,
    results: results,
    turtleInterpretation: interpretResults(results, query),
    nextSteps: `
Found ${results.length} matching patterns in the library.

**What to do next:**
1. Read the matching files in FLAT-LIBRARY/
2. Use related skills to implement them
3. Check examples/ folders for working code
    `
  }
}

/**
 * TURTLE-specific design tips per genre
 */
function getTurtleDesignTips(genre) {
  const tips = {
    '2d-platformer': [
      'Use pixel art or vector graphics for clean 2D aesthetic',
      'Orthographic camera keeps everything crisp',
      'Physics-based platformers need responsive input feedback',
      'Visual feedback (screen shake, particles) is crucial for feel'
    ],
    '3d-action': [
      'Third-person camera is most player-friendly',
      'Real-time shadows make combat readable',
      'Weapon trails and impact particles sell the action',
      'Performance matters — optimize before gameplay gets heavy'
    ],
    'puzzle-game': [
      'Clear visual hierarchy — let players "read" the puzzle at a glance',
      'Satisfying feedback when solving (particles, sounds, UI animations)',
      'Grid-based layouts are easier to design and debug',
      'Accessibility is critical — colorblind-friendly palettes'
    ],
    'vr-experience': [
      'Comfort first — smooth locomotion, avoid disorienting motion',
      'Hands/controllers are the UI',
      'Scale matters — test with real VR headsets early',
      'Performance is safety — 90 FPS minimum'
    ],
    'isometric-rpg': [
      'Fixed isometric angle keeps a consistent, readable view',
      'Grid-based movement is intuitive for players',
      'Layered sprites create depth without 3D',
      'UI anchors to screen corners, not world space'
    ],
    'arcade-game': [
      'Quick visual readability — score, lives, hazards obvious at a glance',
      'Particle effects and screen shake are your best friends',
      'Simple color palettes are timeless (Pac-Man, Asteroids still hold up)',
      'Leaderboard UI = motivation (big, prominent, satisfying)'
    ]
  }

  return tips[genre] || tips['arcade-game']
}

/**
 * Find related skills for a given skill
 */
function getRelatedSkills(skillName) {
  const skillGroups = {
    'threejs-scene-setup': ['threejs-lighting', 'threejs-camera-systems', 'threejs-materials'],
    'threejs-physics': ['ecs-framework', 'game-qa-performance'],
    'threejs-shaders': ['threejs-materials', 'threejs-postprocessing'],
    'ecs-framework': ['threejs-physics', 'game-qa-performance'],
    'game-qa-performance': ['game-qa-mobile', 'threejs-postprocessing']
  }

  return skillGroups[skillName] || []
}

/**
 * Find example code for a skill
 */
function findSkillExamples(skillName) {
  const genreExamples = mcp.listGenres()
  return genreExamples
    .filter(g => g.hasExamples)
    .map(g => ({
      genre: g.name,
      path: `GENRE-TEMPLATES/${g.name}/examples/`
    }))
}

/**
 * Interpret search results in TURTLE's context
 */
function interpretResults(results, query) {
  const categories = {}
  results.forEach(r => {
    if (!categories[r.category]) categories[r.category] = []
    categories[r.category].push(r.file)
  })

  let interpretation = `**Patterns found in ${Object.keys(categories).length} categories:**\n\n`
  for (const [cat, files] of Object.entries(categories)) {
    interpretation += `**${cat}** (${files.length} files)\n`
    files.forEach(f => {
      interpretation += `  • ${f}\n`
    })
  }

  return interpretation
}

/**
 * Main TURTLE interface handler
 */
function handleTurtleRequest(input) {
  const command = parseCommand(input)

  if (command.confidence < 0.5) {
    return {
      error: 'Could not understand request',
      parsed: command,
      examples: [
        '"Build me a 3D action game scaffold"',
        '"Show me how to use shaders"',
        '"Search for particle effects"'
      ]
    }
  }

  const result = executeTurtleCommand(command)

  // Add metadata
  result.commandParsed = command
  result.isFromTurtle = true

  return result
}

module.exports = {
  parseCommand,
  executeTurtleCommand,
  buildScaffold,
  explainSkill,
  searchPatterns,
  handleTurtleRequest,
  getTurtleDesignTips
}

