import assert from 'node:assert/strict';
import { deflateSync } from 'node:zlib';
import { decodePng, encodePng } from './png.mjs';
import { frameMetrics, diffImages } from './metrics.mjs';
import { analyze } from './analyze.mjs';
import { compareReports } from './compare.mjs';
import { isLocalUrl, validate, LIMITS } from './index.mjs';

const test = (name, fn) => { fn(); console.log('ok  ' + name); };

const solid = (w, h, [r, g, b]) => { const d = new Uint8ClampedArray(w * h * 4); for (let i = 0; i < w * h; i++) d.set([r, g, b, 255], i * 4); return { width: w, height: h, data: d }; };
const noisy = (w, h) => { const d = new Uint8ClampedArray(w * h * 4); let s = 1; for (let i = 0; i < w * h; i++) { s = (s * 1103515245 + 12345) >>> 0; d.set([s >>> 24, (s >>> 16) & 255, (s >>> 8) & 255, 255], i * 4); } return { width: w, height: h, data: d }; };

// Build a PNG that uses a chosen row filter, so every decoder branch is exercised.
function pngWithFilter(img, filter) {
  const { width: w, height: h, data } = img, stride = w * 4, rows = Buffer.alloc(h * (stride + 1));
  const px = (y, x) => (x < 0 || y < 0 ? 0 : data[y * stride + x]);
  for (let y = 0; y < h; y++) {
    rows[y * (stride + 1)] = filter;
    for (let x = 0; x < stride; x++) {
      const cur = data[y * stride + x], a = px(y, x - 4), b = px(y - 1, x), c = px(y - 1, x - 4);
      let pred = 0;
      if (filter === 1) pred = a; else if (filter === 2) pred = b; else if (filter === 3) pred = (a + b) >> 1;
      else if (filter === 4) { const p = a + b - c, pa = Math.abs(p - a), pb = Math.abs(p - b), pc = Math.abs(p - c); pred = pa <= pb && pa <= pc ? a : pb <= pc ? b : c; }
      rows[y * (stride + 1) + 1 + x] = (cur - pred) & 255;
    }
  }
  const e = encodePng({ width: 1, height: 1, data: new Uint8ClampedArray(4) });          // borrow signature + IHDR layout
  const head = Buffer.from(e.subarray(0, 8 + 25)); head.writeUInt32BE(w, 16); head.writeUInt32BE(h, 20);
  // recompute IHDR crc by re-encoding via encodePng's own chunker: simplest is to splice real data
  return { raw: rows, head };
}

test('PNG round-trips through encode → decode', () => {
  const img = noisy(17, 9), back = decodePng(encodePng(img));
  assert.equal(back.width, 17); assert.equal(back.height, 9);
  assert.deepEqual(Array.from(back.data), Array.from(img.data));
});

test('decoder handles every PNG row filter (sub, up, average, paeth)', () => {
  const img = noisy(12, 8);
  for (const f of [1, 2, 3, 4]) {
    const { raw } = pngWithFilter(img, f);
    // wrap `raw` as a real PNG using the same chunk writer: encodePng of a 1px image gives us framing to copy
    const base = encodePng(img);                              // valid PNG with filter 0; swap its IDAT payload
    const idatAt = base.indexOf('IDAT') - 4, len = base.readUInt32BE(idatAt);
    const z = deflateSync(raw);
    // rebuild: signature+IHDR, new IDAT (crc recomputed by re-using encodePng via a tiny shim), IEND
    const out = Buffer.concat([base.subarray(0, idatAt), idatChunk(z), base.subarray(idatAt + 12 + len)]);
    const back = decodePng(out);
    assert.deepEqual(Array.from(back.data), Array.from(img.data), 'filter ' + f);
  }
});

function idatChunk(body) {                                      // local chunk writer with crc
  const T = new Uint32Array(256); for (let n = 0; n < 256; n++) { let c = n; for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1; T[n] = c >>> 0; }
  const tag = Buffer.from('IDAT'), all = Buffer.concat([tag, body]); let c = 0xffffffff; for (const b of all) c = T[(c ^ b) & 255] ^ (c >>> 8);
  const out = Buffer.alloc(12 + body.length); out.writeUInt32BE(body.length, 0); tag.copy(out, 4); body.copy(out, 8); out.writeUInt32BE((c ^ 0xffffffff) >>> 0, 8 + body.length); return out;
}

test('decoder rejects non-PNG and unsupported formats clearly', () => {
  assert.throws(() => decodePng(Buffer.from('hello')), /not a PNG/);
});

test('metrics: black frame vs busy frame', () => {
