"""Side-by-side comparison of two generated models: size, geometry, and where each came from."""
from __future__ import annotations

import json
from pathlib import Path

from .glbcheck import inspect_file
from .provenance import sidecar_path


def _record(model: Path) -> dict:
    side = sidecar_path(model)
    try:
        return json.loads(side.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}


def compare(a: str | Path, b: str | Path) -> dict:
    """Return per-field values and the ratio b/a for the numeric ones."""
    a, b = Path(a), Path(b)
    sa, sb = inspect_file(a).as_dict(), inspect_file(b).as_dict()
    fields = {}
    for key in sa:
        va, vb = sa[key], sb[key]
        fields[key] = {"a": va, "b": vb, "ratio": round(vb / va, 3) if va else None}
    ra, rb = _record(a), _record(b)
    return {
        "fields": fields,
        "backend": {"a": ra.get("backend", {}).get("name"), "b": rb.get("backend", {}).get("name")},
        "licence": {"a": ra.get("licence", {}).get("id"), "b": rb.get("licence", {}).get("id")},
        "lighter": "a" if sa["bytes"] < sb["bytes"] else "b" if sb["bytes"] < sa["bytes"] else "same",
    }

"""Optional mesh finishing: cut a generated model down to a face budget for real-time use.

Needs `trimesh` and `fast_simplification` (pip install trimesh fast_simplification).
Without them the pipeline still works; it just cannot decimate.
"""
from __future__ import annotations

from pathlib import Path


class FinishUnavailable(RuntimeError):
    pass


def decimate(src: Path, dst: Path, target_faces: int) -> str:
    """Write a reduced copy of `src` to `dst`; return a short note for the provenance record."""
    try:
        import trimesh
    except ImportError as exc:
        raise FinishUnavailable("install trimesh and fast_simplification to use --faces") from exc
    scene = trimesh.load(str(src), force="scene")
    total = sum(len(g.faces) for g in scene.geometry.values() if hasattr(g, "faces"))
    if total <= target_faces:
        dst.write_bytes(src.read_bytes())
        return f"decimate: skipped ({total} faces already within {target_faces})"
    ratio = target_faces / total
    for name, geom in list(scene.geometry.items()):
        if hasattr(geom, "simplify_quadric_decimation"):
            want = max(4, int(len(geom.faces) * ratio))
            try:
                scene.geometry[name] = geom.simplify_quadric_decimation(face_count=want)
            except ModuleNotFoundError as exc:
                raise FinishUnavailable("install fast_simplification to use --faces") from exc
    scene.export(str(dst))
    kept = sum(len(g.faces) for g in scene.geometry.values() if hasattr(g, "faces"))
    return f"decimate: {total} -> {kept} faces (target {target_faces})"

"""Read-only inspection of binary glTF (.glb) files using only the standard library.

A generated model is worthless if it is truncated or empty, so every output passes
through `inspect_glb` before it is accepted.
"""
from __future__ import annotations

import json
import struct
from dataclasses import dataclass
from pathlib import Path

_MAGIC = 0x46546C67          # "glTF"
_CHUNK_JSON = 0x4E4F534A     # "JSON"
_CHUNK_BIN = 0x004E4942      # "BIN\0"
_TRIANGLES = 4               # glTF primitive mode for a plain triangle list


class GlbError(ValueError):
    """The file is not a usable binary glTF."""


@dataclass(frozen=True)
class GlbStats:
    meshes: int
    materials: int
    images: int
    triangles: int
    bytes: int

    def as_dict(self) -> dict:
        return {"meshes": self.meshes, "materials": self.materials, "images": self.images,
                "triangles": self.triangles, "bytes": self.bytes}


def inspect_glb(data: bytes) -> GlbStats:
    if len(data) < 20:
        raise GlbError("file too small to be a GLB")
    magic, version, total = struct.unpack_from("<III", data, 0)
    if magic != _MAGIC:
        raise GlbError("missing glTF magic header")
    if version != 2:
        raise GlbError(f"unsupported glTF version {version}")
    if total != len(data):
        raise GlbError(f"declared length {total} does not match actual {len(data)} (truncated?)")

    doc, pos = None, 12
    while pos + 8 <= len(data):
        size, kind = struct.unpack_from("<II", data, pos)
        pos += 8
        chunk = data[pos:pos + size]
        if len(chunk) != size:
            raise GlbError("chunk runs past end of file")
        if kind == _CHUNK_JSON and doc is None:
            try:
                doc = json.loads(chunk.decode("utf-8").rstrip(" \x00"))
            except (UnicodeDecodeError, json.JSONDecodeError) as exc:
                raise GlbError(f"unreadable JSON chunk: {exc}") from exc
        pos += size
    if doc is None:
        raise GlbError("no JSON chunk")

    meshes = doc.get("meshes", [])
    if not meshes:
        raise GlbError("model contains no meshes")
    accessors = doc.get("accessors", [])
    triangles = 0
    for mesh in meshes:
        for prim in mesh.get("primitives", []):
            if prim.get("mode", _TRIANGLES) != _TRIANGLES:
                continue
            ref = prim.get("indices")
            if ref is None:
                ref = prim.get("attributes", {}).get("POSITION")
            if ref is None or ref >= len(accessors):
                raise GlbError("primitive references a missing accessor")
            triangles += accessors[ref].get("count", 0) // 3
    if triangles == 0:
        raise GlbError("model has zero triangles")
    return GlbStats(len(meshes), len(doc.get("materials", [])), len(doc.get("images", [])),
                    triangles, len(data))


def inspect_file(path: str | Path) -> GlbStats:
    return inspect_glb(Path(path).read_bytes())

"""Provenance sidecars: a small JSON record that travels with every generated model.

It records what went in, what made it, under which licence, and the hash of what came out.
`verify` recomputes the hashes, so a model that was swapped or a record that was edited by
hand is detected.
"""
from __future__ import annotations

import hashlib
import json
import os
from datetime import datetime, timezone
from pathlib import Path

SCHEMA = "atelier3d.provenance/1"


def sha256_file(path: str | Path) -> str:
    h = hashlib.sha256()
    with open(path, "rb") as fh:
        for block in iter(lambda: fh.read(1 << 20), b""):
            h.update(block)
    return h.hexdigest()


def sidecar_path(model: str | Path) -> Path:
    return Path(f"{model}.provenance.json")


def _digest(record: dict) -> str:
    body = {k: v for k, v in record.items() if k != "record_digest"}
    return hashlib.sha256(json.dumps(body, sort_keys=True, separators=(",", ":")).encode()).hexdigest()


def build(*, input_meta: dict, model: Path, backend: dict, params: dict, license_id: str,
          license_name: str, commercial_use: bool, warnings: list[str], stats: dict,
          started: float, finished: float, finish_steps: list[str]) -> dict:
    iso = lambda t: datetime.fromtimestamp(t, timezone.utc).isoformat(timespec="seconds")
    record = {
        "schema": SCHEMA,
        "input": input_meta,
        "output": {"name": model.name, "sha256": sha256_file(model), "stats": stats},
        "backend": backend,
        "params": params,
        "licence": {"id": license_id, "name": license_name, "declared_commercial_use": commercial_use,
                    "warnings": warnings},
        "finish": finish_steps,
        "started": iso(started),
        "finished": iso(finished),
    }
    record["record_digest"] = _digest(record)
    return record


def write(record: dict, model: str | Path) -> Path:
    path = sidecar_path(model)
    tmp = path.with_suffix(".tmp")
    tmp.write_text(json.dumps(record, indent=2, sort_keys=True), encoding="utf-8")
    os.replace(tmp, path)            # atomic: readers never see half a file
    return path


def load_digest(record_path: str | Path) -> str | None:
    """The tamper-evidence digest of an existing record, used to link a child result to its parent."""
    try:
        return json.loads(Path(record_path).read_text(encoding="utf-8")).get("record_digest")
    except (OSError, json.JSONDecodeError):
        return None


def verify(model: str | Path) -> list[str]:
    """Return a list of problems; empty means the model and its record agree."""
    model = Path(model)
    side = sidecar_path(model)
    if not model.exists():
        return [f"model not found: {model}"]
    if not side.exists():
        return [f"no provenance record next to {model.name}"]
    try:
        record = json.loads(side.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        return [f"provenance record is not valid JSON: {exc}"]
    problems = []
    if record.get("schema") != SCHEMA:
        problems.append(f"unknown schema {record.get('schema')!r}")
    if record.get("record_digest") != _digest(record):
        problems.append("record was edited after it was written")
    if record.get("output", {}).get("sha256") != sha256_file(model):
        problems.append("model file does not match the recorded hash")
    return problems

"""Point-cloud files (.ply) — read, validate and write, standard library only.

A point cloud is the middle stage of text/image → points → mesh pipelines, so it gets the same
treatment as a finished model: it is checked, hashed and recorded. Supports binary little-endian
and ASCII PLY with float/double x,y,z and optional 8-bit red,green,blue.
"""
from __future__ import annotations

import math
import struct
from dataclasses import dataclass
from pathlib import Path


class PlyError(ValueError):
    pass


@dataclass(frozen=True)
class PlyStats:
    points: int
    bounds_min: tuple[float, float, float]
    bounds_max: tuple[float, float, float]
    has_color: bool
    bytes: int

    def as_dict(self) -> dict:
        return {"points": self.points, "bounds_min": list(self.bounds_min),
                "bounds_max": list(self.bounds_max), "has_color": self.has_color, "bytes": self.bytes}


_FMT = {"float": "f", "float32": "f", "double": "d", "float64": "d", "uchar": "B", "uint8": "B",
        "char": "b", "int8": "b", "ushort": "H", "uint16": "H", "short": "h", "int16": "h",
        "uint": "I", "uint32": "I", "int": "i", "int32": "i"}


def _parse_header(data: bytes):
    end = data.find(b"end_header")
    if not data.startswith(b"ply") or end < 0:
        raise PlyError("not a PLY file")
    nl = data.find(b"\n", end)
    if nl < 0:
        raise PlyError("header is not terminated")
    lines = data[:nl].decode("ascii", "replace").replace("\r", "").split("\n")
    fmt, count, props, in_vertex = None, None, [], False
    for line in lines[1:]:
        parts = line.split()
        if not parts:
            continue
        if parts[0] == "format":
            fmt = parts[1]
        elif parts[0] == "element":
            in_vertex = parts[1] == "vertex"
            if in_vertex:
                count = int(parts[2])
        elif parts[0] == "property" and in_vertex:
            if parts[1] == "list":
                raise PlyError("list properties on vertices are not supported")
            if parts[1] not in _FMT:
                raise PlyError(f"unsupported property type {parts[1]}")
            props.append((parts[2], parts[1]))
    if fmt not in ("binary_little_endian", "ascii"):
        raise PlyError(f"unsupported PLY format {fmt!r}")
    if count is None or count <= 0:
        raise PlyError("file has no vertices")
    names = [n for n, _ in props]
    if not {"x", "y", "z"} <= set(names):
        raise PlyError("vertices need x, y and z")
    return fmt, count, props, nl + 1


def inspect_ply(data: bytes) -> PlyStats:
    fmt, count, props, start = _parse_header(data)
    names = [n for n, _ in props]
    xi, yi, zi = names.index("x"), names.index("y"), names.index("z")
    lo, hi = [math.inf] * 3, [-math.inf] * 3

    def take(row):
        for axis, idx in enumerate((xi, yi, zi)):
            v = float(row[idx])
            if not math.isfinite(v):
                raise PlyError("point cloud contains NaN or infinity")
            lo[axis] = min(lo[axis], v)
            hi[axis] = max(hi[axis], v)

    if fmt == "ascii":
        rows = data[start:].decode("ascii", "replace").split("\n")
        rows = [r.split() for r in rows if r.strip()]
        if len(rows) < count:
            raise PlyError("fewer points than the header declares")
        for r in rows[:count]:
            take(r)
    else:
        record = struct.Struct("<" + "".join(_FMT[t] for _, t in props))
        if len(data) - start < count * record.size:
            raise PlyError("file is truncated")
        for row in record.iter_unpack(data[start:start + count * record.size]):
            take(row)
    if lo == hi:
        raise PlyError("every point is in the same place")
    return PlyStats(count, tuple(lo), tuple(hi), {"red", "green", "blue"} <= set(names), len(data))


def inspect_file(path: str | Path) -> PlyStats:
    return inspect_ply(Path(path).read_bytes())


def write_ply(path: str | Path, points: list[tuple[float, float, float]],
              colors: list[tuple[int, int, int]] | None = None) -> None:
    if colors is not None and len(colors) != len(points):
        raise ValueError("colors and points must be the same length")
    props = "property float x\nproperty float y\nproperty float z\n"
    if colors is not None:
        props += "property uchar red\nproperty uchar green\nproperty uchar blue\n"
    header = f"ply\nformat binary_little_endian 1.0\nelement vertex {len(points)}\n{props}end_header\n"
    rec = struct.Struct("<fffBBB" if colors is not None else "<fff")
    body = b"".join(rec.pack(*p, *c) if colors is not None else rec.pack(*p)
                    for p, c in zip(points, colors or points))
    Path(path).write_bytes(header.encode("ascii") + body)

"""Backends turn one image into one .glb. Two kinds ship here:

* CommandBackend — runs any local program (a model on your GPU, a script) without a shell.
* JobBackend     — talks to a hosted service that works as submit → poll → download.

Both are described in a JSON config so adding a service never means editing code:

    {"backends": {
       "local-gpu": {"kind": "command", "command": ["python", "run.py", "{image}", "{out}"],
                      "license": "hunyuan-community", "version": "2.1", "timeout": 1800},
       "hosted":    {"kind": "job", "submit_url": "https://api.example/v1/jobs",
                      "status_url": "https://api.example/v1/jobs/{id}", "token_env": "MY_API_KEY",
                      "license": "service-terms"}}}
"""
from __future__ import annotations

import base64
import json
import os
import subprocess
import time
import urllib.request
from dataclasses import dataclass, field
from pathlib import Path
from typing import Callable, Protocol


class BackendError(RuntimeError):
    pass


class Backend(Protocol):
    name: str
    license_id: str
    version: str

    def generate(self, image: Path, out: Path, params: dict) -> None: ...


@dataclass
class CommandBackend:
    name: str
    command: list[str]
    license_id: str = "unknown"
    version: str = ""
    timeout: int = 1800

    def generate(self, image: Path, out: Path, params: dict) -> None:
        values = {**{k: str(v) for k, v in params.items()}, "image": str(image), "input": str(image), "out": str(out)}
        argv = [part.format(**values) for part in self.command]
        try:
            done = subprocess.run(argv, capture_output=True, text=True, timeout=self.timeout, check=False)
        except FileNotFoundError as exc:
            raise BackendError(f"{self.name}: program not found: {argv[0]}") from exc
        except subprocess.TimeoutExpired as exc:
            raise BackendError(f"{self.name}: timed out after {self.timeout}s") from exc
        if done.returncode != 0:
            tail = (done.stderr or done.stdout or "").strip().splitlines()[-3:]
            raise BackendError(f"{self.name}: exited {done.returncode}: {' | '.join(tail)}")


def _http(method: str, url: str, headers: dict, body: bytes | None) -> tuple[int, bytes]:
    req = urllib.request.Request(url, data=body, method=method, headers=headers)
    with urllib.request.urlopen(req, timeout=120) as resp:      # noqa: S310 — URL comes from your own config
        return resp.status, resp.read()


@dataclass
class JobBackend:
    name: str
    submit_url: str
    status_url: str                      # contains {id}
    license_id: str = "service-terms"
    version: str = ""
    token_env: str = ""
    poll_seconds: float = 3.0
    max_wait: float = 900.0
    transport: Callable[[str, str, dict, bytes | None], tuple[int, bytes]] = field(default=_http, repr=False)
    sleep: Callable[[float], None] = field(default=time.sleep, repr=False)

    def _headers(self) -> dict:
        h = {"Content-Type": "application/json"}
        if self.token_env:
            token = os.environ.get(self.token_env)
            if not token:
                raise BackendError(f"{self.name}: environment variable {self.token_env} is not set")
            h["Authorization"] = f"Bearer {token}"
        return h

    def generate(self, image: Path, out: Path, params: dict) -> None:
        if params.get("mode") == "text":
            payload = {"prompt": params.get("prompt", ""), "params": {k: v for k, v in params.items() if k != "prompt"}}
        else:
            payload = {"image_base64": base64.b64encode(image.read_bytes()).decode(), "params": params}
        status, body = self.transport("POST", self.submit_url, self._headers(), json.dumps(payload).encode())
        if status >= 300:
            raise BackendError(f"{self.name}: submit failed with HTTP {status}")
        job = json.loads(body).get("id")
        if not job:
            raise BackendError(f"{self.name}: submit response had no job id")
        waited = 0.0
        while waited <= self.max_wait:
            status, body = self.transport("GET", self.status_url.format(id=job), self._headers(), None)
            info = json.loads(body)
            state = info.get("status")
            if state == "done":
                url = info.get("result_url")
                if not url:
                    raise BackendError(f"{self.name}: finished without a result_url")
                _, data = self.transport("GET", url, {}, None)
                out.write_bytes(data)
                return
            if state == "failed":
                raise BackendError(f"{self.name}: job failed: {info.get('error', 'no detail')}")
            self.sleep(self.poll_seconds)
            waited += self.poll_seconds
        raise BackendError(f"{self.name}: gave up after {self.max_wait:.0f}s")


def load_config(path: str | Path) -> dict[str, Backend]:
    spec = json.loads(Path(path).read_text(encoding="utf-8")).get("backends", {})
    found: dict[str, Backend] = {}
    for name, cfg in spec.items():
        kind = cfg.get("kind")
        common = {"license_id": cfg.get("license", "unknown"), "version": str(cfg.get("version", ""))}
        if kind == "command":
            found[name] = CommandBackend(name, list(cfg["command"]), timeout=int(cfg.get("timeout", 1800)), **common)
        elif kind == "job":
            found[name] = JobBackend(name, cfg["submit_url"], cfg["status_url"], token_env=cfg.get("token_env", ""),
                                     poll_seconds=float(cfg.get("poll_seconds", 3)), **common)
        else:
            raise BackendError(f"backend {name!r}: unknown kind {kind!r}")
    return found
